const projectList = document.querySelector("#project-list");

function renderProjects() {
  const projectsPerPage = 4;
  const projectProgress = document.querySelector(".projects-progress");
  const projectControls = document.querySelector(".project-slider-controls");

  if (!sideProjects.length) {
    projectList.innerHTML = `
      <div class="empty-projects">
        <div>
          <strong>NEXT BUILD LOADING</strong>
          <span>This space is reserved for the apps still taking shape.</span>
        </div>
      </div>
    `;
    projectControls.hidden = true;
    return;
  }

  const projectPages = [];

  for (let index = 0; index < sideProjects.length; index += projectsPerPage) {
    projectPages.push(sideProjects.slice(index, index + projectsPerPage));
  }

  projectList.innerHTML = projectPages
    .map(
      (projects, pageIndex) => `
        <div class="project-page${pageIndex === 0 ? " is-active" : ""}">
          ${projects
            .map(
              (project) => `
        <a
          class="side-project"
          href="${project.url || "#"}"
          style="--project-accent: ${project.accent || "#2c8cff"}"
          ${project.url ? 'target="_blank" rel="noreferrer"' : ""}
        >
          <span class="side-project-icon">
            <img src="${project.icon}" alt="" />
          </span>
          <span>
            <strong>${project.name}</strong>
            <small>${project.description || "New project details coming soon."}</small>
          </span>
        </a>
              `,
            )
            .join("")}
        </div>
      `,
    )
    .join("");

  projectProgress.innerHTML = projectPages
    .map((_, index) => `<span${index === 0 ? ' class="is-active"' : ""}></span>`)
    .join("");
  projectControls.hidden = projectPages.length < 2;
}

const contactCard = document.querySelector("#contact-card");
const contactTrigger = document.querySelector(".contact-trigger");
const closeContact = document.querySelector(".close-contact");
const contactBack = document.querySelector("#contact-back");

function setContactOpen(isOpen) {
  contactCard.classList.toggle("is-flipped", isOpen);
  contactTrigger.setAttribute("aria-expanded", String(isOpen));
  contactBack.setAttribute("aria-hidden", String(!isOpen));

  if (isOpen) {
    window.setTimeout(() => closeContact.focus(), 360);
  } else {
    contactTrigger.focus();
  }
}

contactTrigger.addEventListener("click", () => setContactOpen(true));
closeContact.addEventListener("click", () => setContactOpen(false));

function initSlideshow({ slideSelector, dotSelector, previousSelector, nextSelector, delay }) {
  const slides = Array.from(document.querySelectorAll(slideSelector));
  const dots = Array.from(document.querySelectorAll(dotSelector));
  const previousButton = document.querySelector(previousSelector);
  const nextButton = document.querySelector(nextSelector);

  if (!slides.length) {
    return;
  }

  let activeIndex = 0;
  let timer;

  const showSlide = (index) => {
    activeIndex = (index + slides.length) % slides.length;

    slides.forEach((slide, slideIndex) => {
      const isActive = slideIndex === activeIndex;
      slide.classList.toggle("is-active", isActive);
      slide.setAttribute("aria-hidden", String(!isActive));
      slide.tabIndex = isActive ? 0 : -1;
    });

    dots.forEach((dot, dotIndex) => {
      dot.classList.toggle("is-active", dotIndex === activeIndex);
    });
  };

  const stop = () => {
    window.clearInterval(timer);
    timer = undefined;
  };

  const start = () => {
    if (!timer && slides.length > 1) {
      timer = window.setInterval(() => showSlide(activeIndex + 1), delay);
    }
  };

  const move = (direction) => {
    stop();
    showSlide(activeIndex + direction);
    start();
  };

  previousButton?.addEventListener("click", () => move(-1));
  nextButton?.addEventListener("click", () => move(1));

  document.addEventListener("visibilitychange", () => {
    if (document.hidden) {
      stop();
    } else {
      start();
    }
  });

  showSlide(activeIndex);
  start();
}

